import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import type { PrimitiveProps } from "../primitives";

const BLUE_DEEP = "#0A1F5C";
const BLUE_MID = "#1747B8";
const BLUE_LIGHT = "#3B7BFF";

const BlueStaticDrift: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();
  const t = frame / fps;

  // Grain re-seeds every 3 frames; seed cycles so it never runs out.
  const seed = Math.floor(frame / 3) % 60;

  // Scan band: slow repeating roll from top to bottom (12s period).
  const rollPeriod = 12 * fps;
  const rollPhase = (frame % rollPeriod) / rollPeriod;
  const bandY = interpolate(rollPhase, [0, 1], [-20, 120], {
    easing: Easing.inOut(Easing.sin),
  });

  // Soft glow breathing and drifting (periodic).
  const glowX = 50 + Math.sin(t * 0.15) * 18;
  const glowY = 40 + Math.cos(t * 0.11) * 14;
  const glowOpacity = 0.45 + Math.sin(t * 0.25) * 0.1;

  // Gentle grain intensity pulse.
  const grainOpacity = 0.09 + Math.sin(t * 0.4) * 0.02;

  return (
    <AbsoluteFill
      style={{
        background: `linear-gradient(180deg, ${BLUE_DEEP} 0%, ${BLUE_MID} 55%, ${BLUE_DEEP} 100%)`,
        overflow: "hidden",
      }}
    >
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at ${glowX}% ${glowY}%, ${BLUE_LIGHT} 0%, rgba(59,123,255,0) 55%)`,
          opacity: glowOpacity,
        }}
      />

      <AbsoluteFill style={{ opacity: grainOpacity, mixBlendMode: "screen" }}>
        <svg width="1080" height="1920" viewBox="0 0 1080 1920">
          <filter id="blue-static-drift-noise">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.85"
              numOctaves={2}
              seed={seed}
              stitchTiles="stitch"
            />
            <feColorMatrix type="saturate" values="0" />
          </filter>
          <rect width="1080" height="1920" filter="url(#blue-static-drift-noise)" />
        </svg>
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          backgroundImage:
            "repeating-linear-gradient(0deg, rgba(0,0,0,0.18) 0px, rgba(0,0,0,0.18) 2px, rgba(0,0,0,0) 2px, rgba(0,0,0,0) 6px)",
          opacity: 0.35,
        }}
      />

      <AbsoluteFill
        style={{
          background: `linear-gradient(180deg, rgba(120,170,255,0) ${bandY - 8}%, rgba(120,170,255,0.10) ${bandY}%, rgba(120,170,255,0) ${bandY + 8}%)`,
        }}
      />

      <AbsoluteFill
        style={{
          background:
            "radial-gradient(ellipse at center, rgba(0,0,0,0) 55%, rgba(3,10,35,0.55) 100%)",
        }}
      />
    </AbsoluteFill>
  );
};

export default BlueStaticDrift;
